sealed class LiliaFfiException: kotlin.Exception() {
    
    class Storage(
        
        val v1: kotlin.String
        ) : LiliaFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class InvalidInput(
        
        val v1: kotlin.String
        ) : LiliaFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class NotFound(
        
        val v1: kotlin.String
        ) : LiliaFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Conflict(
        
        val v1: kotlin.String
        ) : LiliaFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Crypto(
        
        val v1: kotlin.String
        ) : LiliaFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Generic(
        
        val v1: kotlin.String
        ) : LiliaFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LiliaFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): LiliaFfiException = FfiConverterTypeLiliaFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeLiliaFfiError : FfiConverterRustBuffer<LiliaFfiException> {
    override fun read(buf: ByteBuffer): LiliaFfiException {
        

        return when(buf.getInt()) {
            1 -> LiliaFfiException.Storage(
                FfiConverterString.read(buf),
                )
            2 -> LiliaFfiException.InvalidInput(
                FfiConverterString.read(buf),
                )
            3 -> LiliaFfiException.NotFound(
                FfiConverterString.read(buf),
                )
            4 -> LiliaFfiException.Conflict(
                FfiConverterString.read(buf),
                )
            5 -> LiliaFfiException.Crypto(
                FfiConverterString.read(buf),
                )
            6 -> LiliaFfiException.Generic(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LiliaFfiException): ULong {
        return when(value) {
            is LiliaFfiException.Storage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is LiliaFfiException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is LiliaFfiException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is LiliaFfiException.Conflict -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is LiliaFfiException.Crypto -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is LiliaFfiException.Generic -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: LiliaFfiException, buf: ByteBuffer) {
        when(value) {
            is LiliaFfiException.Storage -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is LiliaFfiException.InvalidInput -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is LiliaFfiException.NotFound -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is LiliaFfiException.Conflict -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is LiliaFfiException.Crypto -> {
                buf.putInt(5)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is LiliaFfiException.Generic -> {
                buf.putInt(6)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalLong: FfiConverterRustBuffer<kotlin.Long?> {
    override fun read(buf: ByteBuffer): kotlin.Long? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterLong.read(buf)
    }

    override fun allocationSize(value: kotlin.Long?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterLong.allocationSize(value)
        }
    }

    override fun write(value: kotlin.Long?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterLong.write(value, buf)
        }
    }
}




